(async()=>{try{if(!navigator.locks)throw Error('請使用新版瀏覽器');await navigator.locks.request(Summon.key,()=>Onboarding.migrate(localStorage));const owned=Summon.load(localStorage).owned,growth=Starboard.load(localStorage);for(const h of HeroData.heroes.filter(h=>h.rarity)){const n=owned[h.id]||0,unlocked=h.id==='garnet'?growth.unlocked:growth.starboards?.[h.id]||[],card=document.createElement('article');card.className='card '+h.rarity;card.innerHTML=`<img src="${h.portrait}" alt="${h.name}"><small>${h.rarity} · ${h.role}</small><h2>${h.name}</h2><p>${n?'Lv.'+(unlocked.length+1)+'／50 · 專屬印記 '+(n-1):'尚未取得'}</p><p>普攻：${h.skills.basic}<br>必殺：${h.skills.ultimate}</p><p>${h.skills.description||''}</p>`;if(n){const a=document.createElement('a');a.href='starboard.html?hero='+h.id;a.textContent='查看星盤與培養';card.append(a)}document.querySelector('#collection').append(card)}}catch(e){document.querySelector('#notice').textContent=e.message}})();
